def no_of_subsequences(arr, k):
    """Write a function to find the number of subsequences having product smaller than k for the given non negative array."""
    if not arr:
        return 0

    # If any element can decrease a product (0 < x < 1) or is negative,
    # pruning products >= k is unsafe, so keep every product.
    needs_full = False
    for x in arr:
        if x < 0 or (0 < x < 1):
            needs_full = True
            break

    if needs_full:
        dp = {1: 1}
        for x in arr:
            for prod, cnt in list(dp.items()):
                new_prod = prod * x
                dp[new_prod] = dp.get(new_prod, 0) + cnt
        total = sum(cnt for prod, cnt in dp.items() if prod < k)
        if 1 < k:
            total -= 1  # remove empty subsequence
        return total

    # Optimized path: every element is 0 or >= 1, so products are
    # monotone non-decreasing when adding elements. Zeroes are separated
    # because 0 can bring a previously >= k product below k.
    zero_count = 0
    non_zero = []
    for x in arr:
        if x == 0:
            zero_count += 1
        else:
            non_zero.append(x)
    m = len(non_zero)

    dp = {1: 1}
    for x in non_zero:
        for prod, cnt in list(dp.items()):
            new_prod = prod * x
            if new_prod < k:
                dp[new_prod] = dp.get(new_prod, 0) + cnt

    count_nz = sum(dp.values()) - 1  # remove empty subsequence
    if count_nz < 0:
        count_nz = 0

    if zero_count and k is not None and k > 0:
        # Every subset containing at least one zero has product 0 < k.
        count_nz += ((1 << zero_count) - 1) * (1 << m)

    return count_nz
